head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.trigger1_onclick = function(e) {
	var value = input1.getValue();
	var value2 = searchbox1.getValue();
	//alert(value + value2)
	localStorage.setItem("log", value + value2);			
	console.log(value, value2);
};

scwin.checkVal = function() {
	return localStorage.getItem('log') == '12341234';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
	WebSquare.wUnit.addCommand("pause", "400");			
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
	WebSquare.wUnit.addCommand("pause", "400");				
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').value = '1234'");

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('searchbox1___input').click()");
	WebSquare.wUnit.addCommand("pause", "400");			
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('searchbox1___input').focus()");
	WebSquare.wUnit.addCommand("pause", "400");				
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('searchbox1___input').value = '1234'");

	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
	WebSquare.wUnit.addCommand("pause", "400");			
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
	WebSquare.wUnit.addCommand("pause", "400");				
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
	WebSquare.wUnit.addCommand("pause", "400");	

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
localStorage.removeItem("log");
